[4762] = {"Der Klippenquell", nil, {"Geht von Auberdine aus nach Norden zum ersten Wasserfall des Klippenquell und entnehmt aus dem Teich dort eine Probe.\n\nKehrt mit der Probe des Klippenquells zu Thundris Windwirker nach Auberdine zur√ºck."}},
[4763] = {"Die verderbten Schwarzfelle", nil, {"F√ºllt die leere S√§uberungsschale am Mondbrunnen in Auberdine.\n\nHolt jeweils eine Probe von Fr√ºchten, N√ºssen und Getreide aus dem Lager der Schwarzfellfurbolgs im Norden.\n\nMischt alles in der Schale und stellt diese bei dem Freudenfeuer neben dem Klippenquell auf H√∂he des n√∂rdlichen Lagers ab und lockt dadurch den Satyrverderber an.\n\nNehmt den Talisman der Verderbnis und bringt ihn zu Thundris Windwirker in Auberdine."}},
